import{_ as o,o as d,c as e,a2 as a}from"./chunks/framework.DHtetOlu.js";const q=JSON.parse('{"title":"Referência da API","description":"","frontmatter":{},"headers":[],"relativePath":"scripting/api.md","filePath":"scripting/api.md"}'),r={name:"scripting/api.md"};function c(i,t,u,n,s,m){return d(),e("div",null,[...t[0]||(t[0]=[a('<h1 id="referencia-da-api" tabindex="-1">Referência da API <a class="header-anchor" href="#referencia-da-api" aria-label="Permalink to &quot;Referência da API&quot;">​</a></h1><p>Os comandos do <a href="./console.html">console</a>, agrupados por objeto. Argumentos entre colchetes são opcionais. Ids são strings (<code>&quot;l3&quot;</code>, <code>&quot;p5&quot;</code>, <code>&quot;n2&quot;</code>); onde se espera um id, também vale o <strong>nome</strong> dado à entidade ou ao nó, e <code>getid(&quot;nome&quot;)</code> devolve o id. Muitos comandos que criam algo aceitam <code>id=</code> (para fixar o id) e <code>name=</code>.</p><h2 id="geometria-—-g" tabindex="-1">Geometria — <code>g</code> <a class="header-anchor" href="#geometria-—-g" aria-label="Permalink to &quot;Geometria — `g`&quot;">​</a></h2><h3 id="entidades" tabindex="-1">Entidades <a class="header-anchor" href="#entidades" aria-label="Permalink to &quot;Entidades&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Comando</th><th>Descrição</th></tr></thead><tbody><tr><td><code>g.point((x, y))</code></td><td>ponto</td></tr><tr><td><code>g.line(a, b, construction=False)</code></td><td>linha; <code>a</code> e <code>b</code> são coordenadas ou ids de pontos</td></tr><tr><td><code>g.circle(centro, r=5)</code></td><td>círculo</td></tr><tr><td><code>g.arc(centro, inicio, fim)</code></td><td>arco anti-horário de <code>inicio</code> a <code>fim</code></td></tr><tr><td><code>g.rectangle(canto, oposto)</code></td><td>retângulo (agrupado, com H/V)</td></tr><tr><td><code>g.rectangle_center(centro, canto)</code></td><td>retângulo simétrico em torno do centro</td></tr></tbody></table><h3 id="restricoes" tabindex="-1">Restrições <a class="header-anchor" href="#restricoes" aria-label="Permalink to &quot;Restrições&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Comando</th><th>Descrição</th></tr></thead><tbody><tr><td><code>g.horizontal(l)</code>, <code>g.vertical(l)</code></td><td>linha (ou dois pontos) horizontal/vertical</td></tr><tr><td><code>g.parallel(a, b)</code>, <code>g.perpendicular(a, b)</code></td><td>duas linhas</td></tr><tr><td><code>g.tangent(a, b)</code></td><td>linha e arco/círculo, ou dois arcos/círculos</td></tr><tr><td><code>g.equal(a, b)</code></td><td>comprimentos ou raios iguais</td></tr><tr><td><code>g.coincident(a, b)</code></td><td>dois pontos no mesmo lugar</td></tr><tr><td><code>g.point_on(p, curva)</code></td><td>ponto sobre a curva</td></tr><tr><td><code>g.midpoint(p, l)</code></td><td>ponto no meio da linha</td></tr><tr><td><code>g.symmetric(p1, p2, axis=&quot;y&quot; | linha)</code></td><td>pontos simétricos em relação a um eixo</td></tr><tr><td><code>g.concentric(c1, c2)</code></td><td>mesmo centro</td></tr><tr><td><code>g.fix(p)</code>, <code>g.unfix(p)</code></td><td>prende/solta um ponto</td></tr><tr><td><code>g.detach(&quot;O&quot;)</code></td><td>solta curvas presas à própria Origem (desenhos antigos)</td></tr></tbody></table><h3 id="cotas-e-variaveis" tabindex="-1">Cotas e variáveis <a class="header-anchor" href="#cotas-e-variaveis" aria-label="Permalink to &quot;Cotas e variáveis&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Comando</th><th>Descrição</th></tr></thead><tbody><tr><td><code>g.distance(a, [b,] &quot;50 mm&quot;)</code></td><td>distância (linha, dois pontos ou ponto-linha)</td></tr><tr><td><code>g.hdistance(a, b, &quot;10 mm&quot;)</code>, <code>g.vdistance(a, b, &quot;10 mm&quot;)</code></td><td>distância horizontal/vertical</td></tr><tr><td><code>g.radius(c, &quot;L/2&quot;)</code>, <code>g.diameter(c, 10)</code></td><td>raio e diâmetro</td></tr><tr><td><code>g.angle(l1, l2, &quot;30 deg&quot;)</code></td><td>ângulo entre linhas</td></tr><tr><td><code>g.set_dimension(&quot;k5&quot;, &quot;g*2&quot;)</code></td><td>muda o valor (ou a expressão) de uma cota</td></tr><tr><td><code>g.value(&quot;k5&quot;)</code></td><td>valor atual de uma cota</td></tr><tr><td><code>g.var(&quot;g&quot;, &quot;0.5 mm&quot;)</code></td><td>cria ou muda uma variável</td></tr><tr><td><code>g.del_var(&quot;g&quot;)</code>, <code>g.rename_var(&quot;g&quot;, &quot;gap&quot;)</code></td><td>apaga e renomeia variáveis</td></tr></tbody></table><h3 id="edicao" tabindex="-1">Edição <a class="header-anchor" href="#edicao" aria-label="Permalink to &quot;Edição&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Comando</th><th>Descrição</th></tr></thead><tbody><tr><td><code>g.trim(curva, (x, y))</code></td><td>tesoura: remove o trecho da curva que contém o ponto</td></tr><tr><td><code>g.delete(ids...)</code></td><td>apaga</td></tr><tr><td><code>g.rename(id, &quot;nome&quot;)</code></td><td>dá nome a uma entidade</td></tr><tr><td><code>g.move(p, (x, y))</code></td><td>move um ponto</td></tr><tr><td><code>g.translate(ids, dx=5, dy=0)</code></td><td>translada</td></tr><tr><td><code>g.rotate(ids, &quot;15 deg&quot;, pivot=(0, 0))</code></td><td>gira</td></tr><tr><td><code>g.set_radius(c, 5)</code></td><td>muda o raio</td></tr><tr><td><code>g.construction(ids, True)</code></td><td>marca como construção</td></tr><tr><td><code>g.offset(ids, &quot;2 mm&quot;)</code>, <code>g.set_offset(g, &quot;-5 mm&quot;)</code></td><td>offset associativo e sua distância</td></tr><tr><td><code>g.mirror(ids, axis=&quot;y&quot;)</code></td><td>espelho associativo (eixo <code>&quot;x&quot;</code>, <code>&quot;y&quot;</code> ou uma linha)</td></tr><tr><td><code>g.array(ids, nx=3, ny=1, dx=&quot;20 mm&quot;, dy=0)</code></td><td>padrão linear</td></tr><tr><td><code>g.array_circular(ids, n=6, angle=&quot;360 deg&quot;, center=(0, 0))</code></td><td>padrão circular</td></tr><tr><td><code>g.set_pattern(g, nx=4, dx=&quot;25 mm&quot;)</code></td><td>muda um padrão</td></tr><tr><td><code>g.group([ids], name=&quot;rotor&quot;)</code>, <code>g.ungroup(g)</code></td><td>agrupa e desagrupa</td></tr><tr><td><code>g.hide(g)</code>, <code>g.show(g)</code></td><td>oculta e mostra um grupo</td></tr></tbody></table><h3 id="consulta-e-problema" tabindex="-1">Consulta e problema <a class="header-anchor" href="#consulta-e-problema" aria-label="Permalink to &quot;Consulta e problema&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Comando</th><th>Devolve / faz</th></tr></thead><tbody><tr><td><code>g.get(id)</code></td><td>a entidade (dicionário)</td></tr><tr><td><code>g.list()</code></td><td>lista de ids</td></tr><tr><td><code>g.measure(a, b)</code></td><td>distância mínima entre duas entidades</td></tr><tr><td><code>g.area(ids)</code></td><td>área fechada pelas curvas</td></tr><tr><td><code>g.dof()</code></td><td>graus de liberdade restantes</td></tr><tr><td><code>g.units(&quot;mm&quot;)</code></td><td>unidade de comprimento do projeto</td></tr><tr><td><code>g.problem(&quot;planar&quot; | &quot;axisymmetric&quot;, depth=&quot;100 mm&quot;)</code></td><td>tipo de problema e profundidade (plano)</td></tr></tbody></table><h2 id="malha-—-m" tabindex="-1">Malha — <code>m</code> <a class="header-anchor" href="#malha-—-m" aria-label="Permalink to &quot;Malha — `m`&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Comando</th><th>Descrição</th></tr></thead><tbody><tr><td><code>m.material(&quot;Cobre&quot;, mur=1, sigma=58, br=0, color=&quot;#e0914f&quot;, bh=[(H, B), ...], kh=, alpha=, ke=, group=)</code></td><td>cria ou edita um material (σ em MS/m, Br em T; <code>bh=None</code> apaga a curva)</td></tr><tr><td><code>m.del_material(nome)</code>, <code>m.duplicate_material(nome)</code>, <code>m.restore_material(nome)</code></td><td>apaga, duplica e restaura o padrão</td></tr><tr><td><code>m.circuit(&quot;Bobina&quot;, current=&quot;10&quot;)</code></td><td>cria ou edita um circuito</td></tr><tr><td><code>m.del_circuit(&quot;Bobina&quot;)</code></td><td>apaga</td></tr><tr><td><code>m.region((x, y), name=, material=, circuit=, current=, turns=, angle=, label=(dx, dy))</code></td><td>atribui à região que contém o ponto; devolve a área</td></tr><tr><td><code>m.regions()</code></td><td>lista <code>[((x, y), área, material)]</code></td></tr><tr><td><code>m.boundary_def(&quot;Nome&quot;, type=, value=, a1=, a2=, c0=, c1=, color=)</code></td><td>cria ou edita um contorno</td></tr><tr><td><code>m.boundary([&quot;l1&quot;, &quot;l2&quot;], &quot;Nome&quot; | &quot;dirichlet&quot; | &quot;neumann&quot; | &quot;periodic&quot; | &quot;antiperiodic&quot; | None)</code></td><td>aplica um contorno às curvas</td></tr><tr><td><code>m.mesh_size((x, y), &quot;0.5 mm&quot; | &quot;auto&quot;)</code></td><td>tamanho do elemento na região</td></tr><tr><td><code>m.curve_size([curvas], &quot;1 mm&quot;)</code></td><td>tamanho ao longo de curvas (<code>None</code> tira)</td></tr><tr><td><code>m.settings(&quot;n1&quot;, size=&quot;2 mm&quot; | &quot;auto&quot;, min_angle=30)</code></td><td>tamanho padrão e qualidade da malha</td></tr><tr><td><code>m.generate(&quot;n1&quot;)</code></td><td>gera a malha</td></tr><tr><td><code>m.add(name=&quot;Malha&quot;)</code>, <code>m.rename(id, nome)</code>, <code>m.remove(id)</code></td><td>nós de malha</td></tr></tbody></table><p>Tipos de contorno em <code>type=</code>: <code>dirichlet</code> (A = value + a1·x + a2·y), <code>neumann</code>, <code>mixed</code> (c0, c1), <code>periodic</code>, <code>antiperiodic</code>.</p><h2 id="metodo-de-resolucao-—-s" tabindex="-1">Método de resolução — <code>s</code> <a class="header-anchor" href="#metodo-de-resolucao-—-s" aria-label="Permalink to &quot;Método de resolução — `s`&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Comando</th><th>Descrição</th></tr></thead><tbody><tr><td><code>s.add_physics(name=&quot;Campo magnético&quot;, circuit=False)</code></td><td>nova física (campo, ou circuito com <code>circuit=True</code>)</td></tr><tr><td><code>s.physics(&quot;n2&quot;, analysis=&quot;magnetostatic&quot; | &quot;harmonic&quot; | &quot;transient&quot;, frequency=, dt=, t_end=, schematic=)</code></td><td>configura a análise (frequência em Hz, tempos em s)</td></tr><tr><td><code>s.solve(&quot;n2&quot;)</code></td><td>resolve (gera a malha antes, se preciso)</td></tr><tr><td><code>s.rename(id, nome)</code>, <code>s.remove(id)</code></td><td>organização</td></tr></tbody></table><h2 id="resultados-—-r" tabindex="-1">Resultados — <code>r</code> <a class="header-anchor" href="#resultados-—-r" aria-label="Permalink to &quot;Resultados — `r`&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Comando</th><th>Descrição</th></tr></thead><tbody><tr><td><code>r.view(&quot;n2&quot;, name=)</code></td><td>nova vista de campo</td></tr><tr><td><code>r.interpolate(&quot;n2&quot;, level=3)</code></td><td>vista interpolada (1 a 6)</td></tr><tr><td><code>r.plot(vista, &quot;surface&quot; | &quot;contour&quot; | &quot;arrow&quot; | &quot;line&quot;, quantity=&quot;b&quot; | &quot;h&quot; | &quot;a&quot; | &quot;j&quot; | &quot;bn&quot; | &quot;bt&quot;)</code></td><td>camada numa vista (ou gráfico sobre linha)</td></tr><tr><td><code>r.show(id, visible=, range=(0, 1.5), n_lines=20, spacing=, scale=, curve=, quantity=, color=, color_by_value=, colormap=, regions=[(x, y)], outputs=[(&quot;fx&quot;, &quot;Fx&quot;)], var_name=, expr=, unit_label=, at_time=, legend=(x, y, s))</code></td><td>opções de uma camada ou item</td></tr><tr><td><code>r.table(&quot;n2&quot;, name=)</code></td><td>nova tabela</td></tr><tr><td><code>r.item(tabela, &quot;circuits&quot; | &quot;lineint&quot; | &quot;surfint&quot; | &quot;formula&quot;, name=)</code></td><td>item de tabela</td></tr><tr><td><code>r.move(camada, vista)</code>, <code>r.duplicate(id)</code>, <code>r.rename(id, nome)</code>, <code>r.remove(id)</code></td><td>organização</td></tr><tr><td><code>r.result(&quot;Fx&quot;, physics=&quot;n2&quot;)</code></td><td>número de uma variável de resultado (no instante mostrado, no transitório)</td></tr><tr><td><code>r.results(&quot;n2&quot;)</code></td><td>lista <code>[(nome, valor, unidade), ...]</code></td></tr><tr><td><code>r.series(&quot;Bobina_I&quot;)</code></td><td>transitório: <code>(tempos em s, valores)</code></td></tr></tbody></table><p>Grandezas das integrais (para <code>outputs=</code>): superfície — <code>area</code>, <code>volume</code>, <code>intA</code>, <code>current</code>, <code>energy</code>, <code>bavg</code>, <code>b2</code>, <code>loss</code>, <code>ironLoss</code>, <code>fx</code>, <code>fy</code>, <code>torque</code>; linha — <code>length</code>, <code>flux</code>, <code>mmf</code>, <code>intB</code>, <code>intBn</code>, <code>bavg</code>, <code>fx</code>, <code>fy</code>, <code>torque</code>. Todas em SI.</p><h2 id="esquematico-—-c" tabindex="-1">Esquemático — <code>c</code> <a class="header-anchor" href="#esquematico-—-c" aria-label="Permalink to &quot;Esquemático — `c`&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Comando</th><th>Descrição</th></tr></thead><tbody><tr><td><code>c.add(name=&quot;Circuito 1&quot;)</code></td><td>novo esquemático</td></tr><tr><td><code>c.part(esq, &quot;V&quot; | &quot;I&quot; | &quot;R&quot; | &quot;L&quot; | &quot;C&quot; | &quot;gnd&quot; | &quot;coil&quot;, x=, y=, rot=, value=, amp=, freq=, phase=, dc=, circuit=)</code></td><td>componente</td></tr><tr><td><code>c.wire(esq, (parte, terminal), (parte, terminal), mid=)</code></td><td>fio entre terminais</td></tr><tr><td><code>c.route(fio, x)</code> ou <code>c.route(fio, y=80)</code></td><td>caminho do fio</td></tr><tr><td><code>c.set(parte, value=, name=)</code>, <code>c.move(parte, (x, y))</code>, <code>c.rotate(parte)</code>, <code>c.remove(parte)</code></td><td>edição</td></tr></tbody></table><h2 id="globais" tabindex="-1">Globais <a class="header-anchor" href="#globais" aria-label="Permalink to &quot;Globais&quot;">​</a></h2><p><code>help()</code>, <code>getid(&quot;nome&quot;)</code>, <code>undo()</code>, <code>redo()</code>, <code>fit()</code>, <code>reset()</code>. <code>clear()</code> e <code>next_id(n)</code> aparecem no script exportado.</p>',25)])])}const h=o(r,[["render",c]]);export{q as __pageData,h as default};
